const assert = require("node:assert/strict");
const { existsSync, readFileSync, readdirSync } = require("node:fs");
const path = require("node:path");
const { test } = require("node:test");
const vm = require("node:vm");

const { WWW } = require("./harness.cjs");

// taskmate-localize.js loads one bundle per screen (cards, editor, panel) in
// the user's language, generated by scripts/split_locales.py, instead of the
// whole catalogue twice (the language plus en-GB) with a never-cached URL.

const LOCALES = path.join(WWW, "locales");
const sources = {};
const source = (lang) => (sources[lang] ??= JSON.parse(readFileSync(path.join(LOCALES, `${lang}.json`), "utf8")));
const LANGS = readdirSync(LOCALES).filter((f) => f.endsWith(".json")).map((f) => f.slice(0, -5));

/** Evaluate the module with a fake fetch that serves the real bundle files. */
function loadModule({ guess = "en-GB", missing = [], pathname = "/lovelace/0", version = "7.8.0", stored = null, ha = null } = {}) {
  const fetched = [];
  const events = [];
  const fetch = async (url) => {
    fetched.push(url);
    const rel = url.split("?")[0].replace(/^\/taskmate\/locales\//, "");
    const file = path.join(LOCALES, rel);
    if (missing.some((m) => rel.startsWith(m)) || !existsSync(file)) return { ok: false, status: 404 };
    const body = readFileSync(file, "utf8");
    return { ok: true, json: async () => JSON.parse(body) };
  };
  const window = {
    localStorage: { getItem: (k) => (k === "selectedLanguage" && stored ? JSON.stringify(stored) : null) },
    location: { pathname },
    dispatchEvent: (e) => events.push(e.type),
  };
  const sandbox = {
    window,
    fetch,
    document: ha
      ? { documentElement: { lang: guess }, querySelector: (sel) => (sel === "home-assistant" ? ha : null) }
      : { documentElement: { lang: guess } },
    navigator: { language: "en-GB" },
    CustomEvent: class {
      constructor(type) {
        this.type = type;
      }
    },
    URL,
    encodeURIComponent,
    setTimeout,
  };
  const url = version ? `http://localhost/taskmate/taskmate-localize.js?v=${version}` : "http://localhost/taskmate/taskmate-localize.js";
  const src = readFileSync(path.join(WWW, "taskmate-localize.js"), "utf8").replaceAll("import.meta.url", JSON.stringify(url));
  vm.runInNewContext(src, sandbox);
  const settle = () => new Promise((r) => setTimeout(r, 0)).then(() => new Promise((r) => setTimeout(r, 0)));
  return { t: window.__taskmate_localize, load: window.__taskmate_loadTranslations, fetched, events, settle, sandbox };
}

/** What the old loader returned: the first truthy value down pt-BR → pt → en-GB, else en-GB's. */
function oldResolve(lang, key) {
  const chain = [lang];
  if (lang.includes("-") && LANGS.includes(lang.split("-")[0])) chain.push(lang.split("-")[0]);
  for (const c of chain) {
    const v = source(c)[key];
    if (v) return v;
  }
  const fb = source("en-GB")[key];
  return fb === undefined ? key : fb;
}

test("a dashboard fetches only the cards bundle, once, cache-busted by the integration version", async () => {
  const m = loadModule({ guess: "de" });
  m.t({ language: "de" }, "common.today");
  await m.settle();
  assert.deepEqual(m.fetched, ["/taskmate/locales/de/cards.json?v=7.8.0"]);
  assert.equal(m.t({ language: "de" }, "common.today"), source("de")["common.today"]);
  assert.ok(m.events.includes("taskmate-locale-loaded"), "the panel listens for this to redraw");
});

test("every key, in every language, reads exactly what the old loader returned", async () => {
  for (const lang of LANGS) {
    const m = loadModule({ guess: lang });
    await m.load({ language: lang }, ["cards", "editor", "panel"]);
    const hass = { language: lang };
    for (const key of Object.keys(source("en-GB"))) {
      assert.equal(m.t(hass, key), oldResolve(lang, key), `${lang}: ${key}`);
    }
    assert.equal(m.fetched.length, 3, `${lang} fetched ${m.fetched}`);
  }
});

test("a card key never pulls the panel or editor bundle", async () => {
  const m = loadModule({ guess: "fr" });
  for (const key of ["common.today", "child.all_done", "kiosk.who", "notify.tour_hello_title", "badge.tier_gold"]) {
    m.t({ language: "fr" }, key);
  }
  await m.settle();
  assert.deepEqual(m.fetched, ["/taskmate/locales/fr/cards.json?v=7.8.0"]);
});

test("editor and panel strings come from their own bundles, in the last language seen", async () => {
  const m = loadModule({ guess: "nl" });
  m.t({ language: "nl" }, "common.today");
  await m.load(null, ["editor"]);
  assert.deepEqual(m.fetched, ["/taskmate/locales/nl/cards.json?v=7.8.0", "/taskmate/locales/nl/editor.json?v=7.8.0"]);
  assert.equal(m.t({ language: "nl" }, "common.editor.overview_entity"), source("nl")["common.editor.overview_entity"]);
  m.t({ language: "nl" }, "panel.settings_card_design_label");
  await m.settle();
  assert.equal(m.fetched.at(-1), "/taskmate/locales/nl/panel.json?v=7.8.0");
});

test("the admin panel's page starts its bundle with the cards one", async () => {
  const m = loadModule({ guess: "pl", pathname: "/taskmate-admin/chores" });
  await m.settle();
  assert.deepEqual(m.fetched.sort(), ["/taskmate/locales/pl/cards.json?v=7.8.0", "/taskmate/locales/pl/panel.json?v=7.8.0"]);
});

test("regional and unshipped languages map to a shipped one", async () => {
  const cases = { "de-CH": "de", "pt-BR": "pt-BR", "en-US": "en", es: "en-GB", ar: "en-GB" };
  for (const [lang, want] of Object.entries(cases)) {
    const m = loadModule({ guess: lang });
    m.t({ language: lang }, "common.today");
    await m.settle();
    assert.deepEqual(m.fetched, [`/taskmate/locales/${want}/cards.json?v=7.8.0`], lang);
    assert.equal(m.t({ language: lang }, "common.today"), source(want)["common.today"], lang);
  }
});

test("a bundle that fails to load falls back to the en-GB copy", async () => {
  const m = loadModule({ guess: "da", missing: ["da/"] });
  m.t({ language: "da" }, "common.today");
  await m.settle();
  assert.deepEqual(m.fetched, ["/taskmate/locales/da/cards.json?v=7.8.0", "/taskmate/locales/en-GB/cards.json?v=7.8.0"]);
  assert.equal(m.t({ language: "da" }, "common.today"), source("en-GB")["common.today"]);
});

test("a key still echoes back until its bundle lands, and a missing key stays recognisable", async () => {
  const m = loadModule({ guess: "en" });
  // Callers rely on `t(key) === key` to spot a missing translation.
  assert.equal(m.t({ language: "en" }, "badge.name_custom_123"), "badge.name_custom_123");
  await m.settle();
  assert.equal(m.t({ language: "en" }, "badge.name_custom_123"), "badge.name_custom_123");
  assert.equal(m.t({ language: "en" }, "panel.assign_<img>_short"), "");
  assert.equal(m.t({ language: "en" }, "child.bonus_tooltip", { name: "$&" }), source("en")["child.bonus_tooltip"].replace("{name}", () => "$&"));
});

test("without a ?v= the bundles are not cached, as before", async () => {
  const m = loadModule({ guess: "en", version: "" });
  await m.settle();
  assert.match(m.fetched[0], /^\/taskmate\/locales\/en\/cards\.json\?v=\d+$/);
});

// #771 gate: an en-GB server with an "en" profile. Home Assistant starts on
// en-GB and switches to en once the profile loads; the page used to fetch both
// en-GB/cards.json and en/cards.json.
function haApp({ language = "en-GB", selectedLanguage = null, profile = "en", connectAfter = 0 } = {}) {
  const asked = [];
  const hass = {
    language,
    selectedLanguage,
    connection: { sendMessagePromise: async (msg) => (asked.push(msg), { value: profile ? { language: profile } : {} }) },
  };
  const ha = { hass: connectAfter ? null : hass };
  if (connectAfter) setTimeout(() => { ha.hass = hass; }, connectAfter);
  return { ha, hass, asked };
}
const wait = (ms) => new Promise((r) => setTimeout(r, ms));

test("a first visit waits for the profile language and fetches one cards bundle", async () => {
  const app = haApp({ connectAfter: 120 });
  const m = loadModule({ guess: "en-GB", ha: app.ha });
  // A card renders while Home Assistant still reports the language it started on.
  assert.equal(m.t({ language: "en-GB" }, "common.today"), "common.today");
  await wait(250);
  await m.settle();
  assert.deepEqual(m.fetched, ["/taskmate/locales/en/cards.json?v=7.8.0"]);
  assert.deepEqual(JSON.parse(JSON.stringify(app.asked)), [{ type: "frontend/get_user_data", key: "language" }]);
  assert.equal(m.t({ language: "en" }, "notify.tour_hello_body"), source("en")["notify.tour_hello_body"]);
});

test("without a profile language the start-up language is the one fetched", async () => {
  const app = haApp({ language: "de", profile: null });
  const m = loadModule({ guess: "en-GB", ha: app.ha, pathname: "/taskmate-admin" });
  await wait(20);
  await m.settle();
  assert.deepEqual(m.fetched.sort(), ["/taskmate/locales/de/cards.json?v=7.8.0", "/taskmate/locales/de/panel.json?v=7.8.0"]);
});

test("a language Home Assistant already chose is used straight away", async () => {
  const app = haApp({ language: "nl", selectedLanguage: "nl" });
  const m = loadModule({ guess: "en-GB", ha: app.ha });
  await wait(20);
  await m.settle();
  assert.deepEqual(m.fetched, ["/taskmate/locales/nl/cards.json?v=7.8.0"]);
  assert.deepEqual(app.asked, [], "no need to ask for the profile");
});

test("on a later visit the stored language is preloaded at once, without waiting", async () => {
  const app = haApp({ connectAfter: 5000 });
  const m = loadModule({ guess: "en-GB", stored: "en", ha: app.ha });
  await m.settle();
  assert.deepEqual(m.fetched, ["/taskmate/locales/en/cards.json?v=7.8.0"]);
});

test("an editor asking for its bundle during start-up gets it in the settled language", async () => {
  const app = haApp({ connectAfter: 60 });
  const m = loadModule({ guess: "en-GB", ha: app.ha });
  const loaded = m.load(null, ["editor"]);
  await wait(150);
  await loaded;
  await m.settle();
  assert.deepEqual(m.fetched.sort(), ["/taskmate/locales/en/cards.json?v=7.8.0", "/taskmate/locales/en/editor.json?v=7.8.0"]);
});

test("while a bundle loads, a copy already here is read instead of the raw key", async () => {
  const m = loadModule({ guess: "en-GB" });
  await m.settle();
  assert.deepEqual(m.fetched, ["/taskmate/locales/en-GB/cards.json?v=7.8.0"]);
  // en is not cached yet: the en-GB copy stands in until it lands.
  assert.equal(m.t({ language: "en" }, "common.today"), source("en-GB")["common.today"]);
  await m.settle();
  assert.equal(m.t({ language: "en" }, "notify.tour_hello_body"), source("en")["notify.tour_hello_body"]);
});

test("switching language keeps the old words up until the new ones land", async () => {
  // An "en" profile only ever downloaded en/cards.json; switching to German
  // used to show raw keys until de/cards.json arrived (#771 gate).
  const m = loadModule({ guess: "en" });
  await m.settle();
  assert.equal(m.t({ language: "en" }, "common.today"), source("en")["common.today"]);
  assert.deepEqual(m.fetched, ["/taskmate/locales/en/cards.json?v=7.8.0"]);
  assert.equal(m.t({ language: "de" }, "common.today"), source("en")["common.today"], "no raw key while de loads");
  await m.settle();
  assert.equal(m.t({ language: "de" }, "common.today"), source("de")["common.today"]);
  // On to French: the German words stay up until the French land.
  assert.equal(m.t({ language: "fr" }, "common.today"), source("de")["common.today"]);
});
